begin;
insert into auth.users(id,email,email_confirmed_at) values('00000000-0000-4000-8000-000000102001','team-owner@example.invalid',now()),('00000000-0000-4000-8000-000000102002','team-other@example.invalid',now());
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000102001';
select public.create_business('Team fixture','team-fixture','empresa','mundo-novo-ms') as bid \gset
select public.create_business('Solo fixture','solo-fixture','autonomo','mundo-novo-ms') as solo \gset
select test.assert_true(jsonb_array_length(public.business_team_location(:'bid',true)->'members')=0,'team: empty company');
select public.business_team_location_command(:'bid','save','{"id":"00000000-0000-4000-8000-000000102010","name":"First member","profession":"Barbeiro","specialties":["Corte"],"whatsapp":"5567999999999","consent_version":"team-public-v1","version":0}');
select test.assert_true(jsonb_array_length(public.business_team_location(:'bid',true)->'members')=1,'team: one member persisted');
select test.expect_error(format('select public.business_team_location_command(%L,''save'',''{"id":"00000000-0000-4000-8000-000000102011","name":"No consent"}'')',:'bid'),'23514','team: consent mandatory');
select test.expect_error(format('select public.business_team_location_command(%L,''save'',''{"id":"00000000-0000-4000-8000-000000102011","name":"Solo","consent_version":"team-public-v1"}'')',:'solo'),'23514','team: autonomous has no team');
select test.expect_error(format('select public.business_team_location_command(%L,''save'',''{"id":"00000000-0000-4000-8000-000000102010","name":"Stale","consent_version":"team-public-v1","version":0}'')',:'bid'),'40001','team: stale edit rejected');
select public.business_team_location_command(:'bid','photo_prepare','{"id":"00000000-0000-4000-8000-000000102010","photo_id":"00000000-0000-4000-8000-000000102020","consent_version":"team-public-v1","version":1}');
select test.expect_error(format('select public.business_team_location_command(%L,''photo_finish'',''{"id":"00000000-0000-4000-8000-000000102010","photo_id":"00000000-0000-4000-8000-000000102020","consent_version":"team-public-v1"}'')',:'bid'),'23514','team: missing upload cannot finalize');
insert into storage.objects(bucket_id,name,metadata) values('business-team',:'bid'||'/00000000-0000-4000-8000-000000102010/00000000-0000-4000-8000-000000102020.webp','{"mimetype":"image/webp","size":100}');
select public.business_team_location_command(:'bid','photo_finish','{"id":"00000000-0000-4000-8000-000000102010","photo_id":"00000000-0000-4000-8000-000000102020","consent_version":"team-public-v1"}');
select public.business_team_location_command(:'bid','photo_finish','{"id":"00000000-0000-4000-8000-000000102010","photo_id":"00000000-0000-4000-8000-000000102020","consent_version":"team-public-v1"}');
select test.assert_true((select count(*)=1 from storage.objects where bucket_id='business-team'),'team: idempotent finalize no duplicate');
select public.business_team_location_command(:'bid','photo_prepare','{"id":"00000000-0000-4000-8000-000000102010","photo_id":"00000000-0000-4000-8000-000000102021","consent_version":"team-public-v1","version":2}');
select test.expect_error(format('select public.business_team_location_command(%L,''photo_finish'',''{"id":"00000000-0000-4000-8000-000000102010","photo_id":"00000000-0000-4000-8000-000000102021","consent_version":"team-public-v1"}'')',:'bid'),'23514','team: failed replacement preserves pointer');
select test.assert_true((select photo_path like '%102020.webp' from public.business_team_members where id='00000000-0000-4000-8000-000000102010'),'team: previous portrait intact');
select public.business_team_location_command(:'bid','location','{"mode":"physical","postal_code":"79980000","street":"Rua de teste local","number":"1","neighborhood":"Centro","city_id":"mundo-novo-ms","public_address":false,"version":0}');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000102002';
select test.expect_error(format('select public.business_team_location(%L,true)',:'bid'),'42501','team: other user cannot read private data');
select test.expect_error(format('select public.business_team_location_command(%L,''remove'',''{"id":"00000000-0000-4000-8000-000000102010","version":2}'')',:'bid'),'42501','team: other user cannot remove');
select test.expect_error(format('select public.business_team_location_command(%L,''location'',''{"mode":"home","version":1}'')',:'bid'),'42501','location: other user cannot edit');
select test.assert_true((select count(*)=0 from public.business_team_members),'team: RLS other account');
select test.assert_true((select count(*)=0 from storage.objects where bucket_id='business-team'),'team: draft photo private');
set local role anon;set local request.jwt.claim.sub='';
select test.assert_true(public.business_team_location(:'bid',false)->'location'='null'::jsonb,'location: draft projection empty');
select test.expect_error('select * from public.business_locations','42501','location: no anonymous direct table access');
select test.expect_error(format('select public.business_team_location_command(%L,''location'',''{}'')',:'bid'),'42501','location: anon cannot invoke writes');
reset role;
update public.businesses set status='published' where id=:'bid';
set local role anon;
select test.assert_true((public.business_team_location(:'bid',false)->'location') ? 'street'=false,'location: public profile never exposes private street');
select test.assert_true(jsonb_array_length(public.business_team_location(:'bid',false)->'members')=1,'team: public projection');
select test.assert_true((select count(*)=1 from storage.objects where bucket_id='business-team'),'team: only selected ready photo public');
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000102001';
select public.business_team_location_command(:'bid','location','{"mode":"both","postal_code":"79980000","street":"Rua de teste local","number":"1","neighborhood":"Centro","city_id":"mundo-novo-ms","public_address":true,"version":1}');
select test.expect_error(format('select public.business_team_location_command(%L,''location'',''{"mode":"home","public_address":true,"version":2}'')',:'bid'),'23514','location: home address cannot become public');
-- Exercise 3 and 10; reject the 11th without accounts, conversations or services created for the employees.
select set_config('test.business',:'bid',true);
do $$begin for n in 2..10 loop
 perform public.business_team_location_command(current_setting('test.business')::uuid,'save',jsonb_build_object('id',('00000000-0000-4000-8000-'||lpad((102100+n)::text,12,'0'))::uuid,'name','Local member '||n,'consent_version','team-public-v1','version',0));
 if n=3 then perform test.assert_true(jsonb_array_length(public.business_team_location(current_setting('test.business')::uuid,true)->'members')=3,'team: three members');end if;
end loop;end;$$;
select test.assert_true(jsonb_array_length(public.business_team_location(:'bid',true)->'members')=10,'team: ten members');
select test.expect_error(format('select public.business_team_location_command(%L,''save'',''{"id":"00000000-0000-4000-8000-000000102199","name":"Eleventh member","consent_version":"team-public-v1","version":0}'')',:'bid'),'54000','team: eleventh member rejected');
select test.expect_error('update public.business_team_members set name=''Bypass''','42501','team: owner cannot bypass command validation');
select test.assert_true((select count(*)=1 from public.business_members where business_id=:'bid'),'team: no administrative memberships granted');
select public.business_team_location_command(:'bid','reorder',jsonb_build_object('ids',(select jsonb_agg(id order by position desc,id) from public.business_team_members where business_id=:'bid'),'versions',(select jsonb_object_agg(id,version) from public.business_team_members where business_id=:'bid')));
select test.expect_error(format('select public.business_team_location_command(%L,''reorder'',''{"ids":["00000000-0000-4000-8000-000000102010"],"versions":{}}'')',:'bid'),'23514','team: partial/foreign reorder rejected');
select public.business_team_location_command(:'bid','save',jsonb_build_object('id','00000000-0000-4000-8000-000000102010','name','Edited member','active',false,'consent_version','team-public-v1','version',3));
set local role anon;set local request.jwt.claim.sub='';
select test.assert_true(jsonb_array_length(public.business_team_location(:'bid',false)->'members')=9,'team: hidden member disappears');
select test.assert_true((select count(*)=0 from storage.objects where bucket_id='business-team'),'team: hidden portrait inaccessible');
select test.assert_true(public.business_team_location(:'bid',false)->'location'->>'street'='Rua de teste local','location: confirmed public address');
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000102001';
select public.business_team_location_command(:'bid','remove','{"id":"00000000-0000-4000-8000-000000102010","version":4}');
select test.assert_true((select count(*)=10 from public.business_team_members where business_id=:'bid'),'team: removal retains audit record');
select test.expect_error('select * from private.team_location_audit','42501','team: audit private');
reset role;
select test.assert_true((select count(*)=1 from storage.objects where bucket_id='business-team'),'team: removal never deletes stored files');
insert into private.business_moderation(business_id,suspended) values(:'bid',true);
set local role anon;
select test.assert_true(jsonb_array_length(public.business_team_location(:'bid',false)->'members')=0,'team: suspended business projection empty');
reset role;
rollback;
